//! WP-B6 corpus replay (docs/dev/builtin-corpus.md) for tests/language/builtins/json-parse.json and json-stringify.json,
//! generated by tests/language/gen/gen-b6.mjs. Every case is re-executed through the runtime and compared with the V8 result.
//! A suite must replay with zero failures and zero missing targets. A negative control corrupts one expectation in a copy
//! of the parse suite and requires the replay to report exactly that case.
//!
//! Replay-only realm setup: two cases convert an array argument with ToString, which uses Array.prototype.toString (WP-B2,
//! not installed yet). `replay_realm` installs a stand-in with the ECMA-262 23.1.3.37 behaviour for arrays (join with ","
//! of ToString of each element, undefined and null as ""). It exists only in the replay realm and goes away when WP-B2 lands.

use vn_testkit::{replay_suite, ReplayOptions, ReplayReport};
use vn_value::{Call, Intrinsic, JsStr, PropKey, Res, Rt, Value};

fn replay_realm(rt: &Rt) {
    let array_proto = rt.intrinsic(Intrinsic::ArrayPrototype);
    rt.define_native_method(array_proto, "toString", array_to_string_stand_in, 0);
}

/// Stand-in for Array.prototype.toString in the replay realm: join(",") of the elements' ToString.
fn array_to_string_stand_in(rt: &Rt, c: &Call<'_>) -> Res<Value> {
    let this = Value::Object(rt.to_object(c.this)?);
    let len = rt.get_str(&this, "length")?;
    let len = rt.to_length(&len)? as u32;
    let mut units: Vec<u16> = Vec::new();
    for i in 0..len {
        if i > 0 {
            units.push(u16::from(b','));
        }
        let item = rt.get(rt.to_object(&this)?, &PropKey::Index(i), &this)?;
        if !item.is_nullish() {
            units.extend_from_slice(rt.to_string(&item)?.units());
        }
    }
    Ok(Value::String(JsStr::from_vec(units)))
}

fn replay(text: &str) -> ReplayReport {
    let opts = ReplayOptions { setup: Some(replay_realm), ..Default::default() };
    let report = replay_suite(text, &opts);
    for f in &report.failures {
        eprintln!("{}: FAIL {}: {} (expected {}, actual {})", report.suite, f.id, f.reason, f.expected, f.actual);
    }
    for m in &report.missing {
        eprintln!("{}: MISSING {} ({})", report.suite, m.id, m.target);
    }
    eprintln!("{}: {} of {} cases passed", report.suite, report.passed, report.total);
    report
}

fn assert_clean(report: &ReplayReport) {
    assert!(report.total >= 150, "{}: only {} cases", report.suite, report.total);
    assert!(report.missing.is_empty(), "{}: {} missing targets", report.suite, report.missing.len());
    assert!(report.failures.is_empty(), "{}: {} failing cases", report.suite, report.failures.len());
}

#[test]
fn json_parse_suite_replays_clean() {
    assert_clean(&replay(include_str!("../../../tests/language/builtins/json-parse.json")));
}

#[test]
fn json_stringify_suite_replays_clean() {
    assert_clean(&replay(include_str!("../../../tests/language/builtins/json-stringify.json")));
}

#[test]
fn a_corrupted_expectation_is_reported_as_the_only_failure() {
    let good = include_str!("../../../tests/language/builtins/json-parse.json");
    // The case num/one parses "1" to 1: change its expected result to 2 in a copy of the suite.
    let at = good.find("\"id\":\"num/one\"").expect("case num/one");
    let line_end = at + good[at..].find('\n').expect("end of the case line");
    let ret = at + good[at..line_end].find("\"ret\":1,").expect("expected result of num/one");
    let mut bad = String::with_capacity(good.len());
    bad.push_str(&good[..ret]);
    bad.push_str("\"ret\":2,");
    bad.push_str(&good[ret + "\"ret\":1,".len()..]);
    let report = replay(&bad);
    assert_eq!(report.failures.len(), 1, "exactly the corrupted case must fail");
    assert_eq!(report.failures[0].id, "num/one");
    assert!(report.missing.is_empty());
}
